/* --- primitives --------------------------------------------------------- */

/* thrum_now_ms returns wall-clock milliseconds since the Unix epoch. */
static inline int64_t thrum_now_ms(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (int64_t)ts.tv_sec * 1000 + (int64_t)ts.tv_nsec / 1000000;
}

/* thrum_dusk_in returns the absolute ms timestamp at which a tone with
   this dusk expires. */
static inline int64_t thrum_dusk_in(int64_t ms) { return thrum_now_ms() + ms; }

/* thrum_sigil returns the 12-char content-addressable identifier for a
   (nest, sid) pair: lowercase hex of the first 6 sha256 bytes of
   "nest:sid". Stable across reconnects. */
static inline void thrum_sigil(const char *sid, const char *nest, char out[13]) {
    static const char hexd[] = "0123456789abcdef";
    thrum_sha256 c;
    uint8_t hash[32];
    int i;
    thrum_sha256_init(&c);
    thrum_sha256_update(&c, (const uint8_t *)nest, strlen(nest));
    thrum_sha256_update(&c, (const uint8_t *)":", 1);
    thrum_sha256_update(&c, (const uint8_t *)sid, strlen(sid));
    thrum_sha256_final(&c, hash);
    for (i = 0; i < 6; i++) {
        out[i * 2] = hexd[hash[i] >> 4];
        out[i * 2 + 1] = hexd[hash[i] & 0x0f];
    }
    out[12] = '\0';
}

/* Crockford base32, minus the letters that read like words. */
static const char THRUM_CROCKFORD[33] = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";

/* thrum_humid_encode encodes 32 bytes (48-bit ms prefix + 208 random
   bits, big-endian) as a 52-char Crockford base32 id. Mirrors
   hum_identity's encode bit-for-bit. */
static inline void thrum_humid_encode(const uint8_t buf[32], char out[53]) {
    uint8_t shifted[33];
    int i;
    memset(shifted, 0, sizeof shifted);
    for (i = 0; i < 32; i++) {
        shifted[i] |= (uint8_t)(buf[i] >> 4);
        shifted[i + 1] = (uint8_t)((buf[i] & 0x0f) << 4);
    }
    for (i = 0; i < 52; i++) {
        size_t bit = 4 + (size_t)i * 5;
        size_t byte = bit / 8;
        unsigned off = (unsigned)(bit % 8);
        uint16_t hi = (uint16_t)shifted[byte];
        uint16_t lo = (byte + 1 < 33) ? (uint16_t)shifted[byte + 1] : 0;
        uint16_t window = (uint16_t)((hi << 8) | lo);
        out[i] = THRUM_CROCKFORD[(window >> (11 - off)) & 0x1f];
    }
    out[52] = '\0';
}

/* thrum_is_valid_rid reports whether value is a 52-char Crockford base32
   id. */
static inline bool thrum_is_valid_rid(const char *value) {
    size_t i, len;
    if (!value) return false;
    len = strlen(value);
    if (len != 52) return false;
    for (i = 0; i < len; i++) {
        if (!strchr(THRUM_CROCKFORD, value[i])) return false;
    }
    return true;
}

/* thrum_rid mints a correlation id in canonical HumId form — 52-char
   Crockford base32, ts-prefixed, matching hum_identity::HumId::mint(). */
static inline void thrum_rid(char out[53]) {
    uint8_t buf[32];
    uint64_t ms = (uint64_t)thrum_now_ms();
    FILE *urandom = fopen("/dev/urandom", "rb");
    buf[0] = (uint8_t)((ms >> 40) & 0xff);
    buf[1] = (uint8_t)((ms >> 32) & 0xff);
    buf[2] = (uint8_t)((ms >> 24) & 0xff);
    buf[3] = (uint8_t)((ms >> 16) & 0xff);
    buf[4] = (uint8_t)((ms >> 8) & 0xff);
    buf[5] = (uint8_t)(ms & 0xff);
    if (urandom) {
        if (fread(buf + 6, 1, 26, urandom) != 26) {
            /* Time-seeded fallback rather than mint nothing. */
            size_t i;
            for (i = 6; i < 32; i++) buf[i] = (uint8_t)(ms >> ((i % 8) * 8));
        }
        fclose(urandom);
    } else {
        size_t i;
        for (i = 6; i < 32; i++) buf[i] = (uint8_t)(ms >> ((i % 8) * 8));
    }
    thrum_humid_encode(buf, out);
}

/* thrum_wane is one Lamport clock per sigil. Both sides track their own
   wane; divergence triggers resync via chi:"wane-sync". */
typedef struct {
    const char *sigil;
    int64_t counter;
} thrum_wane;

static inline void thrum_wane_tick(thrum_wane *w) { w->counter += 1; }
static inline bool thrum_wane_behind(const thrum_wane *w, int64_t remote) {
    return remote > w->counter;
}

/* thrum_default_socket_path resolves the humd thrum socket:
   HUM_THRUM_SOCK > HUM_SOCKET > $XDG_STATE_HOME/hum/runtime.json
   (rendezvous) > $XDG_STATE_HOME/hum/thrum.sock. */
static inline bool thrum_default_socket_path(char *out, size_t cap) {
    const char *env;
    const char *home;
    char state[1024];
    char path[1200];
    FILE *f;
    char buf[4096];
    size_t n;

    env = getenv("HUM_THRUM_SOCK");
    if (env && env[0]) {
        snprintf(out, cap, "%s", env);
        return true;
    }
    env = getenv("HUM_SOCKET");
    if (env && env[0]) {
        snprintf(out, cap, "%s", env);
        return true;
    }

    env = getenv("XDG_STATE_HOME");
    if (env && env[0]) {
        snprintf(state, sizeof state, "%s", env);
    } else {
        home = getenv("HOME");
        snprintf(state, sizeof state, "%s/.local/state", home ? home : ".");
    }

    snprintf(path, sizeof path, "%s/hum/runtime.json", state);
    f = fopen(path, "rb");
    if (f) {
        n = fread(buf, 1, sizeof buf - 1, f);
        fclose(f);
        buf[n] = '\0';
        {
            const char *key = "\"socket\"";
            const char *hit = strstr(buf, key);
            if (hit) {
                const char *colon = strchr(hit, ':');
                if (colon) {
                    const char *q = strchr(colon, '"');
                    if (q) {
                        const char *end = strchr(q + 1, '"');
                        if (end) {
                            size_t len = (size_t)(end - q - 1);
                            if (len > 0 && len < cap) {
                                memcpy(out, q + 1, len);
                                out[len] = '\0';
                                return true;
                            }
                        }
                    }
                }
            }
        }
    }

    snprintf(out, cap, "%s/hum/thrum.sock", state);
    return true;
}

